using System;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEditor;using UnityEditor.SceneManagement;
namespace DragonTower.Editor {
 [InitializeOnLoad] public static class CozyValidation {
 static bool done;static CozyValidation(){if(SessionState.GetBool("CozyQA",false))EditorApplication.update+=Tick;}
 public static void Run(){Environment.SetEnvironmentVariable("DRAGON_TOWER_TEST_SAVE","DragonTower.Test.CozyUI");SessionState.SetBool("CozyQA",true);EditorSceneManager.OpenScene("Assets/Scenes/Battle.unity");EditorApplication.EnterPlaymode();}
 static void Check(bool v,string m){if(!v)throw new Exception(m);}
 static void Tick(){if(done||!EditorApplication.isPlaying)return;var f=UnityEngine.Object.FindFirstObjectByType<CollectionFlow>();if(f?.Session==null)return;done=true;try {
 if(f.Session.Selected==null)f.Session.Hatch(0);f.ShowLobby();var b=f.TowerButton;var art=b.GetComponentInChildren<CozySurface>();Check(art!=null&&art.kind==CozySurfaceKind.Primary,"primary");Check(art.GetComponent<CanvasRenderer>()!=null,"renderer required");var r=(RectTransform)b.transform;var position=r.anchoredPosition;var start=art.rectTransform.anchoredPosition;var e=new PointerEventData(EventSystem.current){button=PointerEventData.InputButton.Left};ExecuteEvents.Execute(b.gameObject,e,ExecuteEvents.pointerDownHandler);Check(art.pressed&&r.anchoredPosition==position&&art.rectTransform.anchoredPosition==start+Vector2.down*2,"pressed stable target");ExecuteEvents.Execute(b.gameObject,e,ExecuteEvents.pointerUpHandler);Check(!art.pressed&&art.rectTransform.anchoredPosition==start,"released");b.interactable=false;ExecuteEvents.Execute(b.gameObject,e,ExecuteEvents.pointerDownHandler);Check(!art.pressed,"disabled");b.interactable=true;
 var buttons=UnityEngine.Object.FindObjectsByType<Button>(FindObjectsSortMode.None);buttons.First(x=>x.name=="드래곤 도감"&&x.gameObject.activeInHierarchy).onClick.Invoke();Check(f.ScreenName=="드래곤 도감","codex");Check(UnityEngine.Object.FindObjectsByType<CozyMenuSurface>(FindObjectsSortMode.None).Any(x=>x.gameObject.activeInHierarchy),"codex menu style");f.ShowLobby();buttons=UnityEngine.Object.FindObjectsByType<Button>(FindObjectsSortMode.None);buttons.First(x=>x.name=="드래곤 상태"&&x.gameObject.activeInHierarchy).onClick.Invoke();Check(f.ScreenName=="드래곤 상태","status");Check(UnityEngine.Object.FindObjectsByType<CozyMenuSurface>(FindObjectsSortMode.None).Any(x=>x.gameObject.activeInHierarchy),"status menu style");foreach(var artCheck in UnityEngine.Object.FindObjectsByType<CozyMenuSurface>(FindObjectsSortMode.None))Check(CozyMenuSurface.InScope(artCheck.transform),"menu scope only");f.ShowLobby();Debug.Log("COZY_UI_OK primary pressed release disabled stable-touch-target codex status menu-expansion HUD-scope-guard");SessionState.SetBool("CozyQA",false);EditorApplication.Exit(0);
 }catch(Exception ex){Debug.LogException(ex);SessionState.SetBool("CozyQA",false);EditorApplication.Exit(1);}}
 }
}
